<?php
namespace App\Domain\AI\Knowledge\Models;use App\Domain\AI\Agents\Data\AuthorizedAiLifecycleActor;use App\Domain\AI\Agents\Models\AgentVersion;use App\Domain\AI\Tenancy\AiTenantModel;use App\Models\User;use Illuminate\Database\Eloquent\Relations\BelongsTo;
final class AgentVersionKnowledgeSource extends AiTenantModel{protected$table='ai_agent_version_knowledge_sources';protected$guarded=['*'];public function isAiAppendOnly():bool{return true;}protected function immutableIdentityAttributes():array{return['agent_version_id','knowledge_source_id','knowledge_source_version_id','attached_by_user_id'];}protected static function booted():void{parent::booted();static::creating(function(self$m){$version=KnowledgeSourceVersion::query()->findOrFail($m->knowledge_source_version_id);if((int)$version->knowledge_source_id!==(int)$m->knowledge_source_id||(int)$version->tenant_id!==(int)$m->tenant_id)throw new \DomainException('Knowledge attachment structure is invalid.');$agent=AgentVersion::query()->findOrFail($m->agent_version_id);if((int)$agent->tenant_id!==(int)$m->tenant_id)throw new \DomainException('Knowledge attachment structure is invalid.');});}public function agentVersion():BelongsTo{return$this->belongsTo(AgentVersion::class);}public function source():BelongsTo{return$this->belongsTo(KnowledgeSource::class,'knowledge_source_id');}public function knowledgeVersion():BelongsTo{return$this->belongsTo(KnowledgeSourceVersion::class,'knowledge_source_version_id');}public function actor():BelongsTo{return$this->belongsTo(User::class,'attached_by_user_id');}public function detachAuthorized(AuthorizedAiLifecycleActor$a):void{$this->assertLifecycleActor($a);$this->setKeysForSaveQuery($this->newModelQuery()->toBase())->delete();$this->exists=false;}}
